style.css:
/* Midnight Gambit — Chess.com */

/* swap these colors if you want */
:root {
  --my-black: #171717;
  --my-white: #f2f2f2;
  --my-dark: #242424;
}

/* black and white chessboard */
cg-board {
  background-color: var(--my-white) !important;
  background-image: conic-gradient(
    var(--my-black) 25%,
    var(--my-white) 0 50%,
    var(--my-black) 0 75%,
    var(--my-white) 0
  ) !important;
  background-size: 25% 25% !important;
}

/* dark interface */
body {
  background: var(--my-dark) !important;
  color: var(--my-white) !important;
}

/* monochrome links */
a {
  color: var(--my-white) !important;
}

/* board border */
cg-board {
  border: 2px solid var(--my-black) !important;
}
